'use strict';
const pageLabels={requests:'requests',academies:'academies',create:'create',createReview:'reviewCreate',receipt:'receipt',invitation:'invitation',contexts:'contexts',setup:'setup',branch:'branch',sport:'sport',review:'review',audit:'audit',policies:'policies'};
function navItems(){if(M.studioActive)return studioNav();if(M.labActive)return bnav();return M.persona==='platform'?[['requests','inbox'],['academies','academy'],['audit','shield'],['policies','file']]:[['contexts','switch'],['invitation','person'],['setup','home'],['policies','file']]}
function render(focus=false){document.documentElement.lang=M.lang;document.documentElement.dir=M.lang==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=M.theme;const a=current(),items=navItems();let content=M.studioActive?studioPage():M.labActive&&M.scenario==='restricted'?bhead('lab','Current scope')+notice(t('restricted'),esc(b('policyCopy')),'error'):scenarioPage();if(!content){const routes={requests:platformList,academies:platformList,create:()=>createPage(),createReview:()=>createPage(true),receipt:operationReceipt,invitation:invitationPage,contexts:contextsPage,setup:setupPage,branch:()=>setupForm('branch'),sport:()=>setupForm('sport'),review:reviewSetup,audit:auditPage,policies:policiesPage};content=(trainingRoutes[M.page]||routes[M.page]||platformList)()}
const currentLabel=M.studioActive?sh(M.page):M.labActive?b(M.page):t(pageLabels[M.page]||'requests');document.getElementById('app').innerHTML=`<div class="scene ${M.phone?'phone-mode':''}"><div class="window"><header class="topbar"><div class="crumb">${icon(M.persona==='platform'?'shield':'academy')}<span>${t(M.persona==='platform'?'platform':'workspace')}</span><strong>${esc(currentLabel)}</strong></div><div class="top-actions"><button class="context" data-action="contexts" title="${t('switch')}">${icon('shield')} ${esc(M.studioActive?q('Design studio · review personas','استوديو التصميم · شخصيات المراجعة'):M.labActive?b('opsScope'):M.persona==='platform'?t('platformOwner'):(a?.name||t('recipient')))} ${M.studioActive?'':M.labActive?' · '+b(M.persona==='owner'?'operator':M.persona):M.persona!=='platform'?' · '+t(M.persona==='owner'?'owner':'recipient'):''}</button><button class="icon-btn" data-action="theme" aria-label="Light / dark">${icon('moon')}</button><button class="icon-btn" data-action="language" aria-label="${t('language')}">${icon('globe')}</button></div></header><div class="workspace"><nav class="sidebar" aria-label="Workspace sections"><div class="brand"><span class="logo">A</span><div><b>AcademyOS</b><small>${t(M.persona==='platform'?'platform':'workspace')}</small></div></div><button class="nav-item" data-action="studio-start">${icon('file')}${q('All design journeys','جميع رحلات التصميم')}</button><button class="nav-item" data-action="lab-start">${icon('academy')}${b('lab')}</button><div class="nav-group">${M.labActive?b('simulationOnly'):t(M.persona==='platform'?'platform':'setupOnly')}</div>${items.map(([p,i])=>`<button class="nav-item ${M.page===p?'active':''}" data-action="nav:${p}" ${M.page===p?'aria-current="page"':''}>${icon(i)}${M.studioActive?sh(p):M.labActive?b(p):t(pageLabels[p])}${p==='requests'?`<span class="nav-count">${M.academies.filter(x=>x.owner==='pending').length}</span>`:''}</button>`).join('')}${M.labActive||M.studioActive?'':M.persona==='platform'?`<div class="nav-group">${t('create')}</div><button class="nav-item" data-action="new">${icon('plus')}${t('create')}</button>`:`<div class="nav-group">${t('release')}</div><div class="disabled-nav">${M.lang==='ar'?'الأشخاص · التدريب · المالية · التقارير':'People · Training · Finance · Reports'}<small>${t('noActivation')}</small></div>`}<div class="sidebar-footer"><div class="identity"><span class="avatar">${M.persona==='platform'?'PO':'AO'}</span><span><b>${M.studioActive?q('Review persona fixture','شخصية مراجعة تجريبية'):M.labActive?(M.persona==='trainer'?(B().program?.trainer||'Trainer · demo'):M.persona==='guardian'?'Guardian · demo':'Operator · demo'):M.persona==='platform'?'Moamen · demo':'Alex · demo'}</b><small>${M.studioActive?q('Per-domain authority fixture','سلطة توضيحية لكل مجال'):M.labActive?b(M.persona==='owner'?'operator':M.persona):t(M.persona==='platform'?'platformOwner':M.persona==='owner'?'owner':'recipient')}</small></span></div>${btn(icon('switch')+t('switch'),'contexts')}<small>${t('sim')}</small></div></nav><main class="main" id="main"><div class="mobile-nav"><span class="logo">A</span><select id="mobile-nav" aria-label="Navigation">${items.map(([p])=>`<option value="${p}" ${M.page===p?'selected':''}>${M.studioActive?sh(p):M.labActive?b(p):t(pageLabels[p])}</option>`).join('')}</select></div>${M.toast?`<div class="toast" role="status">${esc(M.toast)}</div>`:''}${content}<p class="batch-label">${t('sim')}<br>${t('source')}${persistAvailable?'':' · Storage unavailable: this demonstration will reset on refresh.'}</p></main>${M.scenario==='happy'&&!M.labActive&&!M.studioActive?inspector():''}</div></div><details class="review-tools" ${M.toolsOpen?'open':''}><summary><span>${t('reviewControls')} · ${M.studioActive?'Batches 3–5':M.labActive?'Batch 2':'Batch 1'}</span><span>${t('notLive')}</span></summary><div class="review-inner"><label>${t('scenario')}<select id="scenario">${(M.studioActive?['happy']:M.labActive?['happy','loading','failed-read','restricted']:['happy','loading','saving','failed-read','no-membership','wrong','expired','revoked','failed-delivery','unknown-delivery','unknown','stale','restricted']).map(s=>`<option value="${s}" ${M.scenario===s?'selected':''}>${esc(({happy:t('happy'),loading:t('loading'),saving:M.lang==='ar'?'جارٍ الحفظ':'Saving', 'failed-read':t('failedRead'),'no-membership':t('noMembership'),wrong:t('wrong'),expired:t('expired'),revoked:t('revoked'),'failed-delivery':t('failed'),'unknown-delivery':t('unknownDelivery'),unknown:t('unknown'),stale:t('stale'),restricted:t('restricted')})[s])}</option>`).join('')}</select></label>${btn(t('apply'),'scenario','small')}${btn(t(M.phone?'desktop':'phone'),'phone','small')}${btn(t('reset'),'reset','small')}${btn(t('backQueue'),'platform','small')}${btn(b('lab'),'lab-start','small')}${btn(q('All design journeys','جميع رحلات التصميم'),'studio-start','small')}<span class="review-note">${t('resume')} ${M.lang==='ar'?'تبديل الأدوار هنا أداة مراجعة، وليس نظام صلاحيات. النتائج والتأخيرات محاكاة يدوية قابلة للتكرار.':'Persona switching is a review tool, not authorization. Results and delays are deterministic manual simulations.'}</span></div></details></div>`;
restoreStudioDrafts();persist();if(focus){document.querySelector('.main').scrollTop=0;document.querySelector('h1')?.focus()} }
function showError(message){M.error=message;render();const error=document.getElementById('form-error');error?.focus();announce(message)}
function readDraft(){if(M.page==='create'){M.draft.name=document.getElementById('academy-name')?.value||'';M.draft.email=document.getElementById('owner-email')?.value||''}else if(M.page==='branch'){M.draft.branch=document.getElementById('branch-name')?.value||'';M.draft.timezone=document.getElementById('timezone')?.value||''}else if(M.page==='sport'){M.draft.sportEn=document.getElementById('sport-en')?.value||'';M.draft.sportAr=document.getElementById('sport-ar')?.value||''}}
function perform(action){if(studioAction(action))return;if(labAction(action))return;const [name,value]=action.split(':');let a=current();if(name==='nav'){changePage(value);return}if(name==='new'){if(M.dirty){changePage('create');return}M.draft={};M.page='create';M.error='';render(true);return}if(name==='language'){if(M.labActive)labRead();else readDraft();M.lang=M.lang==='en'?'ar':'en';render();return}if(name==='theme'){M.theme=M.theme==='light'?'dark':'light';render();return}if(name==='phone'){M.phone=!M.phone;M.toolsOpen=true;render();return}if(name==='reset'){ask(t('reset'),t('resetCopy'),()=>{M=seed();persist();render(true)});return}if(name==='contexts'){changePage('contexts');return}if(name==='platform'){if(M.dirty){ask(t('unsaved'),t('unsavedCopy'),()=>{M.dirty=false;perform('platform')});return}M.labActive=false;M.studioActive=false;M.persona='platform';M.dirty=false;M.draft={};changePage('requests');return}if(name==='recipient'){M.persona=a?.owner==='accepted'?'owner':'recipient';M.page=a?.owner==='accepted'?'contexts':'invitation';M.scenario='happy';render(true);return}if(name==='inspect'){M.selected=value;render();return}if(name==='receipt'){M.selected=value;changePage('receipt');return}if(name==='close-inspector'){M.selected=null;render();return}if(name==='tab'){M.tab=value;render();return}if(name==='filter'){M.filter=value;if(value==='all')M.query='';M.checked=[];render();return}if(name==='clear-selection'){M.checked=[];render();return}if(name==='select-visible'||name==='select-matching'){const ids=filtered().slice(0,name==='select-visible'?25:undefined).map(x=>x.id);M.checked=ids.every(id=>M.checked.includes(id))?M.checked.filter(id=>!ids.includes(id)):[...new Set([...M.checked,...ids])];render();return}
if(name==='create-review'){readDraft();if(!M.draft.name.trim()||!/^\S+@\S+\.\S+$/.test(M.draft.email)){showError(t('required'));return}if(!M.draft.email.endsWith('@example.invalid')){showError(M.lang==='ar'?'استخدم بريداً خيالياً ينتهي بـ example.invalid.':'Use a fictional address ending @example.invalid.');return}M.page='createReview';M.error='';render(true);return}
if(name==='create-commit'){if(!document.getElementById('consequences')?.checked){showError(t('confirmation'));return}const id='DEMO-'+String(M.academies.length+1).padStart(2,'0');a={id,name:M.draft.name.trim(),email:M.draft.email.trim(),owner:'pending',delivery:'queued',invite:'valid',branch:'',timezone:'',sportEn:'',sportAr:'',complete:false,version:1};M.academies.push(a);M.selected=id;a.operation=eventRecord(t('create'),id);M.draft={};M.dirty=false;M.page='receipt';M.error='';render(true);return}
if(name==='correct-identity'){M.scenario='happy';render(true);return}if(name==='accept'){if(!document.getElementById('accept-confirm')?.checked){showError(t('confirmation'));return}if(!a||a.invite!=='valid'||['wrong','expired','revoked'].includes(M.scenario)){showError(t('restricted'));return}a.owner='accepted';M.persona='owner';eventRecord(t('accept'),a.id);M.page='contexts';M.error='';render(true);return}if(name==='choose'){const target=M.academies.find(x=>x.id===value);if(target?.owner!=='accepted'){showError(t('restricted'));return}M.selected=value;M.persona='owner';M.draft={};M.dirty=false;M.page='setup';render(true);return}
if(name==='save'){if(!permitted()||a.complete){showError(t('restricted'));return}readDraft();if(value==='branch'&&(!M.draft.branch.trim()||!M.draft.timezone)||value==='sport'&&(!M.draft.sportEn.trim()||!M.draft.sportAr.trim())){showError(t('required'));return}if(M.scenario==='stale'){M.error=t('stale');M.scenario='happy';M.toast=M.lang==='ar'?'راجعت النسخة الحالية. بقيت المسودة لإعادة التأكيد.':'Current version reviewed. Your draft remains for explicit reapplication.';render();return}Object.assign(a,M.draft);a.version++;eventRecord(t(value),a.id);M.draft={};M.dirty=false;M.error='';M.page='setup';M.toast=t('saved');render(true);return}
if(name==='complete'){if(!permitted()||!a.branch||!a.timezone||!a.sportEn||!a.sportAr){showError(t('required'));return}if(!document.getElementById('setup-confirm')?.checked){showError(t('confirmation'));return}a.complete=true;eventRecord(t('complete'),a.id);M.page='setup';M.error='';render(true);return}
if(name==='withdraw'){ask(t('withdraw'),t('initialOwner'),()=>{if(a.owner==='pending'){a.invite='revoked';eventRecord(t('withdraw'),a.id);render()}});return}if(name==='reissue'){ask(t('reissue'),t('reissued')+' '+t('expiry')+' '+t('noSend'),()=>{if(a.owner==='pending'){a.invite='valid';a.delivery='queued';eventRecord(t('reissue'),a.id);M.toast=t('reissued');render()}});return}if(name==='delivery-retry'||name==='delivery-check'){a.delivery='queued';eventRecord(t(name==='delivery-check'?'checkDelivery':'retryDelivery'),a.id);M.toast=t('noSend');render();return}
if(name==='scenario'){const s=document.getElementById('scenario').value;M.toolsOpen=true;M.scenario=s;if(['wrong','expired','revoked'].includes(s)){if(!a){M.selected=M.academies[0]?.id;a=current()}M.persona='recipient';M.page='invitation'}if(s==='failed-delivery'||s==='unknown-delivery'){if(a){a.delivery=s==='failed-delivery'?'failed':'unknown';M.page='receipt';M.persona='platform';M.scenario='happy'}}if(s==='stale'){M.persona='owner';if(a?.owner!=='accepted')a.owner='accepted';M.page='branch'}if(s==='unknown'){M.unknown={ref:'SIM-CHECK-'+String(M.seq).padStart(4,'0'),page:M.page};}render(true);return}if(name==='recover'||name==='reconcile'){M.scenario='happy';M.toast=name==='reconcile'?(M.lang==='ar'?'فُحصت حالة العملية التجريبية الأصلية. لم يُرسل طلب بديل.':'Original demonstration state checked. No replacement request submitted.'):'';M.unknown=null;render(true);return}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();perform(el.dataset.action)}});
document.addEventListener('change',e=>{if(e.target.dataset.select){const id=e.target.dataset.select;M.checked=e.target.checked?[...new Set([...M.checked,id])]:M.checked.filter(x=>x!==id);render()}if(e.target.id==='mobile-nav')changePage(e.target.value);if(e.target.closest('form')){readDraft();M.dirty=true}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const start=e.target.selectionStart;M.query=e.target.value;M.checked=[];render();const input=document.getElementById('search');input.focus();input.setSelectionRange(start,start)}else if(e.target.closest('form')){readDraft();M.dirty=true}});
document.addEventListener('submit',e=>{e.preventDefault();perform(M.labActive?(M.page==='register'?'bcheckplayer':M.page==='program'?'bpreview':'brequest'):M.page==='create'?'create-review':'save:'+M.page)});
document.addEventListener('toggle',e=>{if(e.target.classList?.contains('review-tools'))M.toolsOpen=e.target.open},true);
render();
